mkdir -p /tmp/pc_test && cat << 'EOF' > /tmp/pc_test/fit.py
import sys, csv, importlib.util, numpy as np, pymc as pm, arviz as az
spec = importlib.util.spec_from_file_location("c", sys.argv[1]); c = importlib.util.module_from_spec(spec); spec.loader.exec_module(c)
rows = list(csv.DictReader(open(sys.argv[2])))
cache = {}
feats = {}
for r in rows:
    k=(r["number_set"], r["target"])
    if k not in cache: cache[k]=c.compute_features(*k)
    for kk,v in cache[k].items(): feats.setdefault(kk,[]).append(v)
data = {k: np.array(v) for k,v in feats.items()}
data["rating"] = np.array([int(r["rating"]) for r in rows])
with c.model:
    pm.set_data(data)
    idata = pm.sample(500, tune=500, chains=4, cores=4, target_accept=0.9, random_seed=1, progressbar=False)
s = az.summary(idata, var_names=[v.name for v in c.model.free_RVs])
print(s.sort_values("r_hat").tail(10)); print("div", int(idata.sample_stats.diverging.sum()))
EOF
